"""Peripheral blocks of the quad-core SoC generated by BARG against hand-written golden models (golden/<name>.py), never shown to the generator.

uart16550f: the SoC's console UART with a 16-byte receive FIFO (the first UART had one receive byte, so Linux could take one keystroke per poll)."""
from __future__ import annotations

import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).parent.parent / "gpu-soc"))
from build_gpu_soc import block, i, o, port  # noqa: E402

W = 32
CLK = port("p_clk", "clk", "in", 1, "clock")
RST = port("p_rst", "rst", "in", 1, "reset")

UART16550F = block("b_uart16550f", "uart16550f", """
    A 16550-style UART with a byte interface and a 16-byte receive FIFO, the register layout NuttX's 16550 driver, Linux's 8250 driver and
    QEMU's virt machine use, one byte per register. addr is the 32-bit address of an access; bits 2:0 pick the register. we is 1 for a store,
    with wdata bits 7:0 the byte stored; re is 1 for a load that will really happen. Held state, all 0 at reset: the interrupt enable register
    IER (4 bits), the line control register LCR (8 bits; its bit 7 is the divisor latch access bit, DLAB), the modem control register MCR (5
    bits), the scratch register SCR (8 bits), the divisor latch low byte DLL and high byte DLM (8 bits each), the FIFO-enabled flag FE, the
    transmit-empty interrupt flag TXF, the overrun flag OE, and the receive FIFO: sixteen bytes of storage (numbered 0 to 15), a read position
    RP (4 bits), a write position WP (4 bits) and the count RXCNT (5 bits, 0 to 16, the number of bytes in the FIFO). The byte at the front of
    the FIFO is the storage byte numbered RP; the FIFO is empty when RXCNT is 0.
    Reads: rdata has the byte in bits 7:0 and 0 in bits 31:8, and depends only on addr and the held state. Offset 0 reads DLL when DLAB is 1;
    when DLAB is 0 it reads the front byte when RXCNT is not 0, and 0 when RXCNT is 0. Offset 1 reads DLM when DLAB is 1 and IER (bits 7:4
    are 0) when DLAB is 0. Offset 2 reads the interrupt identification register: bit 0 is 0 when an interrupt is pending and 1 when none is;
    bits 3:1 are 010 when the receive interrupt is pending, otherwise 001 when the transmit interrupt is pending, otherwise 000; bits 5:4 are
    0; bits 7:6 are 11 when FE is 1 and 00 otherwise. Offset 3 reads LCR. Offset 4 reads MCR (bits 7:5 are 0). Offset 5 reads the line status
    register: bit 0 is 1 when RXCNT is not 0, bit 1 is OE, bits 5 and 6 are 1 (the transmitter is always empty), every other bit is 0. Offset
    6 reads 0 (the modem status register). Offset 7 reads SCR. The receive interrupt is pending when IER bit 0 is 1 and RXCNT is not 0. The
    transmit interrupt is pending when IER bit 1 is 1 and TXF is 1. irq is 1 when the receive interrupt or the transmit interrupt is pending.
    tx_valid is 1 and tx_data is wdata bits 7:0 in a cycle when we is 1, addr bits 2:0 are 0 and DLAB is 0 (a byte to transmit); otherwise
    tx_valid is 0 and tx_data is 0; they depend only on the inputs and the held state.
    On each rising clock edge, when rst is 1 everything held becomes 0 (the sixteen storage bytes too); otherwise these happen in this order,
    a later one overriding an earlier one for the same state. (1) Reads: when re is 1 and addr bits 2:0 are 0 and DLAB is 0 and RXCNT is not
    0, the front byte is removed: RP becomes RP + 1 (modulo 16) and RXCNT becomes RXCNT - 1; when re is 1 and addr bits 2:0 are 5, OE
    becomes 0; when re is 1 and addr bits 2:0 are 2 and the interrupt identification register (as read this cycle) has bits 3:1 equal to 001,
    TXF becomes 0. (2) Stores, by addr bits 2:0 when we is 1: offset 0 with DLAB 1 writes DLL; offset 0 with DLAB 0 transmits the byte and
    sets TXF to 1; offset 1 with DLAB 1 writes DLM; offset 1 with DLAB 0 writes IER (low 4 bits) and, when that write takes IER bit 1 from 0
    to 1, sets TXF to 1; offset 2 sets FE to wdata bit 0 and, when wdata bit 1 is 1, empties the receive FIFO (RP, WP and RXCNT become 0);
    offset 3 writes LCR; offset 4 writes MCR (low 5 bits); offset 7 writes SCR; stores to offsets 5 and 6 change nothing. (3) Receive: when
    rx_valid is 1 and RXCNT (as the steps above left it) is less than 16, the byte rx_data is stored at the storage byte numbered WP, WP
    becomes WP + 1 (modulo 16) and RXCNT becomes RXCNT + 1; when rx_valid is 1 and RXCNT is 16, OE becomes 1 and the byte is lost.
""", [CLK, RST, i("addr", W, "addr"), i("wdata", W), i("we", 1, "control"), i("re", 1, "control"), i("rx_valid", 1, "control"),
      i("rx_data", 8), o("rdata", W), o("irq", 1, "control"), o("tx_valid", 1, "control"), o("tx_data", 8)], reset="sync", latency=1)

BLOCKS = [UART16550F]
